import{_ as l,o as t,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Ceph Month 2021: Ceph Market Development Working Group BoF","description":"","frontmatter":{"title":"Ceph Month 2021: Ceph Market Development Working Group BoF","date":"2021-06-25T00:00:00.000Z","updated":"2021-06-25T00:00:00.000Z","tags":["Ceph","市场发展","分布式存储","软件定义存储","开源社区"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_Ceph_Market_Development_Working_Group_BoF.md","filePath":"posts/2021/Ceph_Month_2021_-_Ceph_Market_Development_Working_Group_BoF.md","lastUpdated":1780459816000}'),i={name:"posts/2021/Ceph_Month_2021_-_Ceph_Market_Development_Working_Group_BoF.md"};function p(r,e,h,n,_,s){return t(),a("div",null,[...e[0]||(e[0]=[o('<p>会议纪要</p><h3 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h3><p>由Softline的营销总监Cameron主持，本次Ceph市场发展组（Ceph Market Development Group）会议讨论了组织的成立背景、目标、工作方式以及未来的行动计划。会议强调了Ceph在软件定义存储市场中的重要性，并旨在提高其认知度和市场占有率。</p><h3 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h3><ol><li><p><strong>Ceph市场发展组的成立背景</strong>：</p><ul><li>由多个供应商组成，旨在提高Ceph在软件定义存储市场中的认知度、理解和考虑度。</li><li>面向企业技术决策者，而非开发者或工程师。</li></ul></li><li><p><strong>为何需要Ceph市场发展组</strong>：</p><ul><li>强调Ceph的成功对所有相关供应商的重要性。</li><li>认识到技术环境的复杂性和竞争性，希望通过提升Ceph的知名度来帮助其在市场中脱颖而出。</li></ul></li><li><p><strong>Ceph市场发展组的工作方式</strong>：</p><ul><li>与Canonical、Red Hat等紧密合作，组成跨供应商的工作组。</li><li>目标是推动商业导向的营销活动，以触及更广泛的受众。</li></ul></li><li><p><strong>Ceph市场发展组的未来行动计划</strong>：</p><ul><li>每两周举行一次会议，制定长期战略。</li><li>向Ceph基金会董事会申请预算，执行一系列营销活动。</li><li>邀请社区成员参与，共同推动Ceph的市场推广。</li></ul></li></ol><h3 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h3><ul><li>确认了Ceph市场发展组的目标和行动计划。</li><li>决定继续使用现有的Ceph用户邮件列表进行沟通，并在主题行中添加特定标签以便识别。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>定期会议，制定和执行营销策略。</li><li>更新和优化Ceph官方网站，增加更多教育内容和案例研究。</li><li>通过社交媒体、搜索引擎营销等渠道，提升Ceph的知名度和市场占有率。</li><li>邀请更多社区成员参与，共同推动Ceph的发展和市场推广。</li></ul><h3 id="其他讨论点" tabindex="-1">其他讨论点 <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点&quot;">​</a></h3><ul><li>讨论了如何更好地整合和展示Ceph社区的工作组信息，以便社区成员更容易参与和了解。</li><li>提到了Ceph官方网站的更新和改进，以及如何通过网站更好地服务社区和潜在用户。</li></ul><p>会议强调了Ceph市场发展组的重要性，并呼吁社区成员积极参与和支持。通过集体努力，目标是提升Ceph的市场地位和认知度，促进其在企业环境中的更广泛应用。</p>',12)])])}const d=l(i,[["render",p]]);export{C as __pageData,d as default};
